import React from 'react';
import { Link } from 'react-router-dom';
import { Container, Box, Typography } from '@mui/material';

function Home() {
  return (
    <Container maxWidth="md" sx={{ mt: 8 }}>
      <Box sx={{ textAlign: 'center', mb: 6 }}>
        <Typography variant="h2" gutterBottom>Welcome to ResumeBuilder</Typography>
        <Typography variant="h5" color="textSecondary">Create a professional resume in minutes with beautiful templates and AI assistance.</Typography>
      </Box>
      <div className="home-page">
        <h1>Welcome to the AI Resume Builder</h1>
        <p>Create a stunning, professional resume in minutes with the power of AI. Choose a template, fill in your details, and download your resume instantly!</p>
        <Link to="/templates" className="get-started-btn">Get Started</Link>
      </div>
    </Container>
  );
}

export default Home;
